// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 depositAmount, uint256 extraFunding) public {
        vm.assume(depositAmount <= VALUE_CAP);
        // Admissible domain: positive, bounded wei amounts so transfers always succeed
        depositAmount = bound(depositAmount, 1, 1 ether);
        extraFunding = bound(extraFunding, 1, 1 ether);

        // owner of c is the test contract (msg.sender in setUp); fund it to receive payouts
        vm.deal(address(this), depositAmount);

        // deposit into c via its payable fallback -> depositsCount = 1
        (bool okDep, ) = address(c).call{value: depositAmount}("");
        assertTrue(okDep);

        // give c additional balance beyond the recorded deposit count
        vm.deal(address(c), address(c).balance + extraFunding);
        uint256 preBalance = address(c).balance;

        // owner withdraws everything
        c.withdrawAll();

        // RULE: withdrawAll empties the contract — remaining balance is exactly 0.
        // Reference: transfers preBalance, balance becomes 0. Mutant: transfers
        // depositsCount (1 wei), leaving preBalance - 1 > 0.
        assertTrue(address(c).balance == 0);
    }

    receive() external payable {}
}
